// ============================================================================
// I2S_Audio_apb: APB4 register wrapper around I2S_Audio_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/I2S_Audio.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/I2S_Audio.md
// ============================================================================
module I2S_Audio_apb #(
  parameter int DW = 32,
  parameter int AW = 32,
  parameter int MCLK_DIV = 4
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic bclk_out,
  output logic wclk_out,
  input logic bclk_in,
  input logic wclk_in,
  output logic sd_out,
  input logic sd_in
);
  localparam logic [31:0] ID_VALUE = 32'h49410200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [9:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd10) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_cfg_master;
  logic [1:0]    c_cfg_fmt;
  logic [1:0]    c_cfg_depth;
  logic [31:0]   c_tx_l;
  logic [31:0]   c_tx_r;
  logic          c_tx_valid;
  logic          c_tx_ready;
  logic [31:0]   c_rx_l;
  logic [31:0]   c_rx_r;
  logic          c_rx_valid;
  logic          c_irq;
  I2S_Audio_top #(.DW(DW), .AW(AW), .MCLK_DIV(MCLK_DIV)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .cfg_master(c_cfg_master),
    .cfg_fmt(c_cfg_fmt),
    .cfg_depth(c_cfg_depth),
    .bclk_out(bclk_out),
    .wclk_out(wclk_out),
    .bclk_in(bclk_in),
    .wclk_in(wclk_in),
    .tx_l(c_tx_l),
    .tx_r(c_tx_r),
    .tx_valid(c_tx_valid),
    .tx_ready(c_tx_ready),
    .rx_l(c_rx_l),
    .rx_r(c_rx_r),
    .rx_valid(c_rx_valid),
    .sd_out(sd_out),
    .sd_in(sd_in),
    .irq(c_irq)
  );

  // ---------------- registers ----------------
  logic [4:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [4:0] r_CFG;   // 12'h014 CFG
  logic [31:0] h_TX0;   // 12'h018 TX0 holding register
  logic [31:0] h_TX1;   // 12'h01C TX1 holding register
  logic [31:0] h_RX0;   // 12'h020 RX0 holding register
  logic [31:0] h_RX1;   // 12'h024 RX1 holding register
  logic full_TX;
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CFG <= 5'h11;
      h_TX0 <= '0;
      h_TX1 <= '0;
      h_RX0 <= '0;
      h_RX1 <= '0;
      full_TX <= 1'b0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[4:0] & wmask[4:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[4:0]) | (PWDATA[4:0] & wmask[4:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CFG <= (r_CFG & ~wmask[4:0]) | (PWDATA[4:0] & wmask[4:0]);
      if (wr && hit[6] && !full_TX) h_TX0 <= (h_TX0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7] && !full_TX) h_TX1 <= (h_TX1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7] && !full_TX) full_TX <= 1'b1;
      else if (full_TX && c_tx_ready) full_TX <= 1'b0;
      if (c_rx_valid && (!avail_RX || (rd && hit[9]))) begin
        h_RX0[31:0] <= c_rx_l[31:0];
        h_RX1[31:0] <= c_rx_r[31:0];
        avail_RX <= 1'b1;
      end else if (rd && hit[9]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_master = r_CFG[0:0];
  assign c_cfg_fmt = r_CFG[2:1];
  assign c_cfg_depth = r_CFG[4:3];
  assign c_tx_l[31:0] = h_TX0[31:0];
  assign c_tx_r[31:0] = h_TX1[31:0];
  assign c_tx_valid = full_TX;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq;
    irq_set[1] = full_TX & c_tx_ready;
    irq_set[2] = wr & (hit[6] | hit[7]) & full_TX;
    irq_set[3] = c_rx_valid & (~avail_RX | (rd & hit[9]));
    irq_set[4] = c_rx_valid & avail_RX & ~(rd & hit[9]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RX, full_TX};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CFG);
      10'd6: apb_rdata = 32'(h_TX0);
      10'd7: apb_rdata = 32'(h_TX1);
      10'd8: apb_rdata = 32'(h_RX0);
      10'd9: apb_rdata = 32'(h_RX1);
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
